"use client";
import { useState } from 'react';
export default function ChatRAG() {
  const [q,setQ]=useState(''); const [a,setA]=useState(''); const [loading,setLoading]=useState(false);
  const ask=async()=>{setLoading(true); const res=await fetch('/api/chat', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({messages:[{role:'user', content:q}], model:'groq/llama-3.3-70b-versatile'})}); const data=await res.json(); setA(data.choices?.[0]?.message?.content||JSON.stringify(data).slice(0,500)); setLoading(false);};
  return (<div className="min-h-screen bg-[#0a0a0f] text-white p-8"><h1 className="text-3xl font-bold">Chat RAG — 200 Providers</h1><p className="text-slate-400 mt-2">RAG com gateway OpenAI-compatible — 200 providers, 181 free, 938 models UAI image video</p><div className="mt-6 flex gap-2"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pergunta com RAG..." className="flex-1 px-4 py-2 rounded-lg bg-[#11111b] border border-[#1e1e2e]"/><button onClick={ask} disabled={loading} className="px-6 py-2 rounded-lg bg-white text-black font-bold disabled:opacity-50">{loading?'...':'Ask'}</button></div><div className="mt-6 p-4 rounded-xl bg-[#11111b] border border-[#1e1e2e] min-h-[200px]">{a||'Resposta RAG aparecerá aqui...'}</div></div>);
}

