import { NextRequest, NextResponse } from 'next/server';
export async function POST(req: NextRequest) {
  const body = await req.json();
  // Proxy para AI Provider OS gateway OpenAI-compatible — 200 providers 938 models UAI
  const res = await fetch('http://localhost:8000/v1/chat/completions', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({...body, stream:false})});
  const data = await res.json();
  return NextResponse.json(data);
}
